// Real BLE GATT access is separate from the simulator network.
export class HostBluetooth {
 constructor(api=globalThis.navigator?.bluetooth){this.api=api;this.device=null;this.rx=null;this.tx=null;this.onData=()=>{};this.onDisconnect=()=>{};}
 async connect(service,rx,tx){if(!this.api?.requestDevice)throw Error('Bu tarayıcı Web Bluetooth desteklemiyor. Chrome veya Edge ile HTTPS adresini açın.');this.disconnect();let device;try{device=await this.api.requestDevice({filters:[{services:[service]}]});this.device=device;this.lost=()=>{this.tx=null;this.rx=null;this.device=null;this.onDisconnect();};device.addEventListener('gattserverdisconnected',this.lost);const server=await device.gatt.connect(),s=await server.getPrimaryService(service);this.tx=await s.getCharacteristic(tx);this.rx=await s.getCharacteristic(rx);if(!this.tx.properties.write&&!this.tx.properties.writeWithoutResponse)throw Error('TX karakteristiği yazılabilir değil.');if(!this.rx.properties.notify&&!this.rx.properties.indicate)throw Error('RX karakteristiği bildirim desteklemiyor.');this.notification=e=>this.onData(new Uint8Array(e.target.value.buffer,e.target.value.byteOffset,e.target.value.byteLength).slice());this.rx.addEventListener('characteristicvaluechanged',this.notification);await this.rx.startNotifications();return device.name||'BLE cihazı';}catch(e){this.disconnect();throw e;}}
 async send(text){if(!this.device?.gatt.connected||!this.tx)throw Error('Gerçek BLE cihazı bağlı değil.');const bytes=new TextEncoder().encode(text);if(!bytes.length||bytes.length>512)throw Error('BLE mesajı: 1–512 bayt.');for(let i=0;i<bytes.length;i+=20){const chunk=bytes.slice(i,i+20);if(this.tx.properties.write)await this.tx.writeValueWithResponse(chunk);else await this.tx.writeValueWithoutResponse(chunk);}}
 disconnect(){this.rx?.removeEventListener('characteristicvaluechanged',this.notification);this.device?.removeEventListener('gattserverdisconnected',this.lost);this.device?.gatt.disconnect();this.rx=null;this.tx=null;this.device=null;}
}
